def find_all_hollow_squares(grid):
    """Find all hollow squares (uniform border)."""
    H, W = len(grid), len(grid[0])
    squares = []

    for size in range(3, min(H, W) + 1):
        for r in range(H - size + 1):
            for c in range(W - size + 1):
                # Check if this forms a hollow square with uniform border
                border = grid[r][c]

                # Check all border cells are the same color
                is_hollow = True

                # Check top and bottom rows
                if not all(grid[r][c+k] == border for k in range(size)):
                    is_hollow = False
                if not all(grid[r+size-1][c+k] == border for k in range(size)):
                    is_hollow = False

                # Check left and right columns
                if not all(grid[r+k][c] == border for k in range(size)):
                    is_hollow = False
                if not all(grid[r+k][c+size-1] == border for k in range(size)):
                    is_hollow = False

                if is_hollow:
                    interior_size = (size - 2) * (size - 2)
                    squares.append({
                        'size': size,
                        'r': r, 'c': c,
                        'border': border,
                        'interior_size': interior_size,
                        'interior_cells': size*size - 4*border
                    })

    return squares

