                for r in range(i+1, i+size-1):
                    for c in range(j+1, j+size-1):
                        if grid[r][c] == border_color:
                            interior_ok = False
                            break

                    if not interior_ok:
                        break

                if interior_ok:
                    squares.append((i, j, size, border_color, inter_area))

    # Maximal filter: keep largest at each position
    from collections import defaultdict
    grouped = defaultdict(list)
    def pos_key(sq):
        r, c, s, _, _ = sq
        return (r, c)

    for sq in squares:
        grouped[pos_key(sq)].append(sq)

    max_squares = []
    for pos, sqs in grouped.items():
        max_squares.append(max(sqs, key=lambda x: x[2]))

    max_squares.sort(key=lambda x: (x[0], x[1]))
    return max_squares

